    e(p.invoice.currency.code + ' ' + p.invoiceAmount) + '</p><p>Status: ' + e(s.status.replaceAll('_', ' ')) +
    '</p><p>Current invoice amount due: ' + e(p.invoice.currency.code + ' ' + s.currentAmountDue) + '</p></section>' +
