    [...value.funding.map(item=>({action:'Released credit',...item})),...value.allocations.map(item=>({action:'Applied payment',...item}))]
      .map(item=>'<tr><td>'+e(item.action)+'</td><td>'+e(item.invoiceNumber)+'</td><td>'+e(item.amount)+'</td></tr>').join('')+
