function receiptBalanceSnapshot(summary) {
  return Object.fromEntries(['id', 'customerId', 'reference', 'method', 'receivedDate', 'currency',
    'amount', 'allocated', 'refunded', 'reserved', 'netAmount', 'available', 'status', 'voidDate', 'asOf']
