}

/** Inspect one retained entry without scanning the entire store. */
export async function readRecoveredSettlement({ recoveredDir, recoveryId } = {}) {
  await directory(recoveredDir);
  return publicEntry(await readEntry(recoveredDir, recoveryId));
}

/** Return the retained delivered bytes. Never contact the merchant or buy again. */
export async function readRecoveredResponse({ recoveredDir, recoveryId } = {}) {
  await directory(recoveredDir);
  const entry = await readEntry(recoveredDir, recoveryId);
  need(entry.data.response !== null, 'RECOVERY_HAS_NO_SAVED_RESPONSE');
  return { ...entry.data.response, recoveryId, byteLength: entry.data.response.bytes,
    bytes: entry.source.get('response.bin') };
