    record.history.push({at:now(),action:recovered?'VERIFICATION_RESULT_RECOVERED':official?'REFUND_VERIFIED':'LOCAL_READ_COMPLETED',
      actor:job.actor,jobId:job.id,transaction:proof.transaction});
