:root {
  color-scheme: dark;
  font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-synthesis: none;
  --bg:#171717; --surface:#212121; --surface-soft:#1b1b1b; --border:#414141;
