h1,h2,h3 { line-height:1.3; font-weight:650; }
h1 { margin:0; font-size:27px; letter-spacing:-.02em; }
h2 { margin:0; font-size:21px; }
h3 { margin:22px 0 10px; font-size:16px; }
p { color:var(--muted); margin:8px 0 14px; }
.header p:last-child { margin-bottom:0; font-size:13px; }
.local-badge,.stage-hint { display:inline-block; flex-shrink:0; border:1px solid var(--border); border-radius:3px; padding:5px 9px; color:var(--muted); font-size:11px; }
main { padding:18px 0 6px; }
.workflow { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); position:sticky; top:8px; z-index:5; border:1px solid var(--border); border-radius:4px; background:var(--surface); }
