.handoff-progress progress::-webkit-progress-value { background:#bbb; }
.handoff-commands { margin:18px 0; }
.handoff-digest { white-space:pre-line; overflow-wrap:anywhere; font:11px/1.7 ui-monospace,monospace; }
.handoff-file-link { color:var(--text); text-underline-offset:3px; }
.handoff-files td:first-child { min-width:180px; }
.boundary { margin:10px 0 18px; font-size:11px; }
.card { padding:24px; margin-bottom:18px; border:1px solid var(--border); border-radius:4px; background:var(--surface); }
.card:target { border-color:#999; }
.section-heading,.split { display:flex; align-items:flex-start; justify-content:space-between; gap:20px; }
.section-heading>div,.split>div:first-child { flex:1; min-width:0; }
.section-heading p:last-child { margin:8px 0 0; max-width:800px; font-size:13px; }
.form-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px 22px; margin-top:20px; }
.form-grid>* { min-width:0; }
.full { grid-column:1/-1; }
label { display:block; color:var(--text); font-size:12px; font-weight:600; }
label small { display:block; margin:3px 0 7px; color:var(--muted); font-size:11px; font-weight:400; }
input:not([type=checkbox]),select,textarea { display:block; width:100%; min-width:0; min-height:38px; margin-top:6px; padding:8px 10px; border:1px solid #626262; border-radius:3px; color:var(--text); background:var(--surface-soft); font:inherit; font-size:13px; font-weight:400; line-height:1.45; }
label small+input,label small+select { margin-top:0; }
input::placeholder,textarea::placeholder { color:#858585; opacity:1; }
input:not([type=checkbox]):hover,select:hover,textarea:hover { border-color:#929292; }
input:not([type=checkbox]):focus,select:focus,textarea:focus { border-color:#eee; }
input:disabled,select:disabled,textarea:disabled { opacity:.65; cursor:not-allowed; }
input[type=checkbox] { width:16px; height:16px; margin:2px 0 0; accent-color:#ddd; flex-shrink:0; }
input[type=file] { padding:4px; font-size:11px; }
