.approval:has(#permission) { padding-top:16px; border-top:1px solid var(--border); }
.actions { display:flex; align-items:center; flex-wrap:wrap; gap:9px; }
button { display:inline-flex; align-items:center; justify-content:center; min-height:36px; max-width:100%; padding:8px 13px; border:1px solid #ddd; border-radius:3px; background:#ddd; color:#171717; font:inherit; font-size:12px; font-weight:650; line-height:1.35; text-align:center; cursor:pointer; }
button:hover:not(:disabled) { background:#fff; border-color:#fff; }
button:active:not(:disabled) { background:#c7c7c7; }
button:disabled { opacity:.45; cursor:not-allowed; }
.secondary { border-color:#626262; color:var(--text); background:#2b2b2b; }
.secondary:hover:not(:disabled) { border-color:#aaa; background:#3a3a3a; }
.text-button,.case-link { min-height:28px; padding:3px 0; border:0; background:transparent; color:var(--text); font-size:12px; text-align:left; justify-content:flex-start; }
.text-button:hover:not(:disabled),.case-link:hover:not(:disabled) { background:transparent; text-decoration:underline; text-underline-offset:3px; }
:where(a,button,input,select,textarea,summary,[tabindex]):focus-visible { outline:2px solid var(--focus); outline-offset:3px; }
.hint { color:var(--muted); font-size:11px; }
.status { margin:18px 0; padding:11px 13px; border:1px solid var(--border); border-left:3px solid #888; border-radius:3px; background:var(--surface-soft); color:#ccc; font-size:12px; overflow-wrap:anywhere; }
.status.busy { border-left-style:dashed; }.status.good { border-left-color:#ddd; }.status.error { border-left-width:5px; border-left-style:double; color:#fff; }
.card .status:last-child { margin-bottom:0; }
.source-details { margin:18px 0; border:1px solid var(--border); border-radius:3px; background:var(--surface-soft); }
.source-details summary { padding:11px 13px; color:#ccc; font-size:12px; cursor:pointer; }
.source-details summary:hover { background:#292929; }
.source-details[open] { padding:0 13px 13px; }.source-details[open]>summary { margin:0 -13px 12px; border-bottom:1px solid var(--border); }
.source-details>p { font-size:12px; }.source-details>:last-child { margin-bottom:0; }
.source-details .form-grid { margin-top:15px; }
.portable-cases { margin-bottom:18px; }.portable-cases .card { margin:0; border:0; padding:5px 0; background:transparent; }
pre { max-width:100%; max-height:340px; margin:12px 0 0; padding:12px; overflow:auto; border:1px solid var(--border); border-radius:3px; background:#151515; color:#d0d0d0; font:11px/1.6 ui-monospace,monospace; tab-size:2; }
.scope { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px; margin-top:18px; }
.scope-row { min-width:0; padding:10px 12px; border:1px solid var(--border); border-radius:3px; background:var(--surface-soft); overflow-wrap:anywhere; }
.scope-row b { display:block; margin-bottom:3px; color:var(--muted); font-size:10px; font-weight:600; }.scope-row span { font-size:12px; }
