/* MIT. Operator workspace: neutral colors, clear tables and explicit controls. */
.planning-back{align-self:center;white-space:nowrap;color:var(--ink,#202327)}
.planning-source{display:grid;grid-template-columns:minmax(220px,1fr) auto;gap:12px;align-items:end;max-width:850px}
