.planning-route-table input{min-width:110px;width:100%;margin-top:0}.planning-route-table td{vertical-align:top}.planning-route-table code{display:block;white-space:normal;overflow-wrap:anywhere}.planning-route-table small{display:block;margin-top:5px}
.planning-review-actions,.planning-save{display:flex;align-items:end;justify-content:space-between;gap:16px}
