const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
const fail=(code,message)=>failure('PRICING_COST_'+code,message);
const inputKinds={SOURCE:'costInputs',BOOK:'costBooks',PACKAGE:'costPackages'};
